Print(Concat('Column A: [', ArrayJoin(columnA, ', '), ']'));
Print(Concat('Sum: ', ToString(Sum(columnA)), ', Mean: ', ToString(Mean(columnA))));

Chart('bar', Array('Row 1', 'Row 2', 'Row 3'), columnA, 'Column A');`}]},{name:"Memory",icon:X(qa),snippets:[{name:"Counters & Variables",description:"Named counters and persisted script variables",code:`// Memory: named counters and persisted script variables
