Print(Concat('95% CI -- [', ToString(ArrayGet(ci, 0)), ', ', ToString(ArrayGet(ci, 1)), ']  mean=', ToString(ArrayGet(ci, 2))));`},{name:"Post-Hoc & Effect Size",description:"Tukey HSD, Bonferroni correction, Cohen's d, eta-squared",code:`// DOE: post-hoc pairwise comparisons and effect sizes
var groupA = Array(20.1, 21.4, 19.8, 22.0, 20.6);
