var etaSq = DoeLibrary.EtaSquared(52.5, 58.66);
Print(Concat('Eta-squared: ', ToString(etaSq)));`},{name:"Descriptive Stats & Gage R&R",description:"The library's own Mean/Variance/StdDev/Correlation, plus Gage R&R",code:`// DOE: the library's own Mean/Variance/StandardDeviation/Correlation (equivalent
// to the plain built-ins already shown in the Statistics category) plus GageRR
var data = Array(12, 15, 14, 10, 18, 21, 14, 16, 13, 19);
Print(Concat('DoeLibrary.Mean: ', ToString(DoeLibrary.Mean(data))));
