var coefficients = ArrayGet(logit, 0);
var standardErrors = ArrayGet(logit, 1);
var zStats = ArrayGet(logit, 2);
var pValues = ArrayGet(logit, 3);
var oddsRatios = ArrayGet(logit, 4);
